static std::vector<BYTE> read(ID3D11Device*d,ID3D11DeviceContext*c,ID3D11Texture2D*t){D3D11_TEXTURE2D_DESC td{};t->GetDesc(&td);td.Usage=D3D11_USAGE_STAGING;td.BindFlags=td.MiscFlags=0;td.CPUAccessFlags=D3D11_CPU_ACCESS_READ;ComPtr<ID3D11Texture2D>s;hr(d->CreateTexture2D(&td,nullptr,&s));c->CopyResource(s.Get(),t);D3D11_MAPPED_SUBRESOURCE m{};hr(c->Map(s.Get(),0,D3D11_MAP_READ,0,&m));std::vector<BYTE> b(size_t(td.Width)*td.Height*4);for(UINT y=0;y<td.Height;++y)memcpy(b.data()+size_t(y)*td.Width*4,(BYTE*)m.pData+y*m.RowPitch,td.Width*4);c->Unmap(s.Get(),0);return b;}
static std::vector<BYTE> readRgba32(ID3D11Device*d,ID3D11DeviceContext*c,ID3D11Texture2D*t){D3D11_TEXTURE2D_DESC td{};t->GetDesc(&td);check(td.Format==DXGI_FORMAT_R32G32B32A32_FLOAT,"RGBA32 readback format");td.Usage=D3D11_USAGE_STAGING;td.BindFlags=td.MiscFlags=0;td.CPUAccessFlags=D3D11_CPU_ACCESS_READ;ComPtr<ID3D11Texture2D>s;hr(d->CreateTexture2D(&td,nullptr,&s));c->CopyResource(s.Get(),t);D3D11_MAPPED_SUBRESOURCE m{};hr(c->Map(s.Get(),0,D3D11_MAP_READ,0,&m));std::vector<BYTE>b(size_t(td.Width)*td.Height*16);for(UINT y=0;y<td.Height;++y)memcpy(b.data()+size_t(y)*td.Width*16,(BYTE*)m.pData+y*m.RowPitch,td.Width*16);c->Unmap(s.Get(),0);return b;}
static std::vector<BYTE> readBuffer(ID3D11Device*d,ID3D11DeviceContext*c,ID3D11Buffer*b){D3D11_BUFFER_DESC bd{};b->GetDesc(&bd);auto staging=bd;staging.Usage=D3D11_USAGE_STAGING;staging.BindFlags=staging.MiscFlags=0;staging.CPUAccessFlags=D3D11_CPU_ACCESS_READ;staging.StructureByteStride=0;ComPtr<ID3D11Buffer>s;hr(d->CreateBuffer(&staging,nullptr,&s));c->CopyResource(s.Get(),b);D3D11_MAPPED_SUBRESOURCE m{};hr(c->Map(s.Get(),0,D3D11_MAP_READ,0,&m));std::vector<BYTE> data(bd.ByteWidth);memcpy(data.data(),m.pData,data.size());c->Unmap(s.Get(),0);return data;}
static std::vector<BYTE> readFile(const wchar_t*path){FILE*f=nullptr;if(_wfopen_s(&f,path,L"rb")||!f)return {};fseek(f,0,SEEK_END);const long n=ftell(f);fseek(f,0,SEEK_SET);std::vector<BYTE>b(n>0?size_t(n):0);if(!b.empty()&&fread(b.data(),1,b.size(),f)!=b.size())b.clear();fclose(f);return b;}
static edvr::Surface surf(ID3D11Device*d,UINT w,UINT h,DXGI_FORMAT f){edvr::Surface s;check(s.ensure(d,w,h,f),"surface created");return s;}
static std::vector<BYTE> programContainer(ID3DBlob* shell,std::vector<UINT> program){using namespace edvr::dxbc_fanout_detail;program[1]=UINT(program.size());const auto*p=static_cast<const BYTE*>(shell->GetBufferPointer());std::vector<BYTE>in(p,p+shell->GetBufferSize());std::vector<std::pair<UINT,std::vector<BYTE>>>chunks;bool replaced=false;for(UINT i=0,n=word(in,28);i<n;++i){UINT off=word(in,32+4*i),tag=word(in,off),size=word(in,off+4);std::vector<BYTE>b(in.begin()+off+8,in.begin()+off+8+size);if(tag==0x58454853||tag==0x52444853){b.resize(program.size()*4);memcpy(b.data(),program.data(),b.size());replaced=true;}chunks.push_back({tag,std::move(b)});}check(replaced,"compiled shader shell has a token program");std::vector<BYTE>out(in.begin(),in.begin()+32);out.resize(32+chunks.size()*4);UINT i=0;for(auto&chunk:chunks){UINT off=UINT(out.size());memcpy(out.data()+32+4*i++,&off,4);put(out,chunk.first);put(out,UINT(chunk.second.size()));out.insert(out.end(),chunk.second.begin(),chunk.second.end());}UINT size=UINT(out.size());memcpy(out.data()+24,&size,4);ComputeHashRetail(out.data()+20,size-20,out.data()+4);return out;}
static std::vector<BYTE> stripRdef(ID3DBlob* shell){using namespace edvr::dxbc_fanout_detail;const auto*p=static_cast<const BYTE*>(shell->GetBufferPointer());std::vector<BYTE>in(p,p+shell->GetBufferSize());std::vector<std::pair<UINT,std::vector<BYTE>>>chunks;bool removed=false;for(UINT i=0,n=word(in,28);i<n;++i){UINT off=word(in,32+4*i),tag=word(in,off),size=word(in,off+4);if(tag==0x46454452u){removed=true;continue;}chunks.push_back({tag,std::vector<BYTE>(in.begin()+off+8,in.begin()+off+8+size)});}check(removed,"compiled fixture contains RDEF");std::vector<BYTE>out(in.begin(),in.begin()+32);out.resize(32+chunks.size()*4);UINT count=UINT(chunks.size());memcpy(out.data()+28,&count,4);UINT i=0;for(auto&chunk:chunks){UINT off=UINT(out.size());memcpy(out.data()+32+4*i++,&off,4);put(out,chunk.first);put(out,UINT(chunk.second.size()));out.insert(out.end(),chunk.second.begin(),chunk.second.end());}UINT size=UINT(out.size());memcpy(out.data()+24,&size,4);ComputeHashRetail(out.data()+20,size-20,out.data()+4);return out;}
static std::vector<BYTE> duplicateProgramChunk(const std::vector<BYTE>&in){using namespace edvr::dxbc_fanout_detail;std::vector<std::pair<UINT,std::vector<BYTE>>>chunks;bool duplicated=false;for(UINT i=0,n=word(in,28);i<n;++i){UINT off=word(in,32+4*i),tag=word(in,off),size=word(in,off+4);std::vector<BYTE>body(in.begin()+off+8,in.begin()+off+8+size);chunks.push_back({tag,body});if(!duplicated&&(tag==0x58454853u||tag==0x52444853u)){chunks.push_back({tag,body});duplicated=true;}}check(duplicated,"duplicate fixture found a program chunk");std::vector<BYTE>out(in.begin(),in.begin()+32);out.resize(32+chunks.size()*4);UINT count=UINT(chunks.size());memcpy(out.data()+28,&count,4);UINT i=0;for(auto&chunk:chunks){UINT off=UINT(out.size());memcpy(out.data()+32+4*i++,&off,4);put(out,chunk.first);put(out,UINT(chunk.second.size()));out.insert(out.end(),chunk.second.begin(),chunk.second.end());}UINT size=UINT(out.size());memcpy(out.data()+24,&size,4);ComputeHashRetail(out.data()+20,size-20,out.data()+4);return out;}
static void fanoutDestinationTests(){using namespace edvr::dxbc_fanout_detail;
 auto unchanged=[](std::vector<UINT> inst,UINT op){auto original=inst;UINT mask=0;rewriteDestinations(inst,op,9,mask);check(inst==original&&mask==0,"multi-destination temp/null instruction remains unchanged");};
 unchanged({0x0600004D,0x00100042,2,0x0000D000,0x0010002A,2},77);
 unchanged({0x0600004D,0x0000D000,0x00100042,2,0x0010002A,2},77);
 unchanged({0x08000026,0x0000D000,0x00100022,3,0x0010003A,2,0x00004001,0x30},38);
 unchanged({0x0800004E,0x0000D000,0x00100082,8,0x0010003A,8,0x00004001,12},78);
 unchanged({0x0B00008E,0x00100072,5,0x00100072,6,0x00100FF6,5,0x00100246,5,0x00100386,4},142);
 {std::vector<UINT> inst{0x0600004D,0x00102042,0,0x0000D000,0x0010002A,2};UINT mask=0;rewriteDestinations(inst,77,9,mask);check(mask==4&&inst[1]==0x00100042&&inst[2]==9,"first sincos output destination is redirected");}
 {std::vector<UINT> inst{0x08000026,0x0000D000,0x00102032,0,0x00100046,0,0x00100AA6,0};UINT mask=0;rewriteDestinations(inst,38,9,mask);check(mask==3&&inst[2]==0x00100032&&inst[3]==9,"second imul output destination is redirected");}
 for(UINT op:{81u,132u,133u}){std::vector<UINT> inst{0x05000000u|op,0x0000D000,0x00100012,1,0};UINT mask=0;rewriteDestinations(inst,op,9,mask);check(mask==0,"remaining SDK two-destination opcode advances both destinations");}
 for(UINT op:{18u,21u,22u,57u}){std::vector<UINT> inst{0x01000000u|op};UINT mask=0;rewriteDestinations(inst,op,9,mask);check(mask==0&&inst.size()==1,"operand-free control instruction remains unchanged");}
 for(UINT token:{0x80500022u,0x00500022u}){bool declined=false;try{std::vector<UINT> inst{0x08000026,0x0000D000,token,3,0,0,0,0};UINT mask=0;rewriteDestinations(inst,38,9,mask);}catch(const std::exception&){declined=true;}check(declined,"extended or relative multi-destination operand declines closed");}
}
static std::vector<UINT> twoDestinationProgram(UINT op,bool outputFirst,UINT sourceCount){std::vector<UINT>p{0x50,0,0x03000065,0x001020f2,0};const UINT length=1+3+5*sourceCount;p.push_back((length<<24)|op);if(outputFirst){p.push_back(0x00102032);p.push_back(0);p.push_back(0x0000d000);}else{p.push_back(0x0000d000);p.push_back(0x00102032);p.push_back(0);}UINT values[3][4]={{1,1,0,0},{0x3f000000,0x3e800000,0,0},{1,1,1,1}};if(op==77){values[0][0]=0x3f000000;values[0][1]=0x3f800000;}if(op==78){values[0][0]=0x3f000000;values[0][1]=0x3e800000;values[1][0]=values[1][1]=1;}for(UINT s=0;s<sourceCount;++s){p.push_back(0x00004002);p.insert(p.end(),values[s],values[s]+4);}const UINT mov[]={0x08000036,0x001020c2,0,0x00004002,0,0,0x3f400000,0x3f800000};p.insert(p.end(),mov,mov+8);p.push_back(0x0100003e);return p;}
